package ama.task;
import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import ama.contract.TaskContracts.*;import ama.contract.ExternalContracts.*;
/** Generic-family regression only; exact fresh Task11 schema, no provider or publication task. */
class Task11AffectedExternalIT {
 @Test void genericMarkerFailureRetryReplayAndCurrentSuccessStillUseOriginalProtocol(){var f=new Task11AffectedFixture();var q=f.queue();var external=new JdbcExternalOperations(q);var spec=f.spec();var request=new ExternalRequest("TEST_CALL",spec.producerKey(),Task11AffectedFixture.hash("logical"+spec.producerKey()),Task11AffectedFixture.hash("execution"+spec.input().id()),"test-v1:"+spec.input().id());var lease=f.claimed(q,spec);var first=external.beginExternal(lease,request).orElseThrow();assertEquals(ObservationResult.APPLIED,external.observe(first,new ExternalObservation(ExternalOutcome.FAILED_ZERO_EFFECT,null,null,"REJECTED",new NoEffectProof(NoEffectBasis.DEFINITIVE_REJECTION,"TEST_VERIFIED_ZERO",Instant.now())),()->{}));var next=new TaskSpec(spec.type(),spec.pool(),spec.subject(),Task11AffectedFixture.hash("next"+spec.producerKey()),spec.input(),spec.inputFingerprint(),0,0,0,3);String accepted=external.retryAfterZeroEffect(first.operationId(),1,next,request);assertEquals(accepted,external.retryAfterZeroEffect(first.operationId(),1,next,request));var retry=q.claim(spec.pool(),"generic-retry").orElseThrow();assertEquals(accepted,retry.taskId());var second=external.beginExternal(retry,request).orElseThrow();assertEquals(2,second.executionNo());assertFalse(external.renew(first));assertEquals(ObservationResult.APPLIED,external.observe(second,new ExternalObservation(ExternalOutcome.SUCCEEDED,"TEST_RESULT:"+spec.input().id(),spec.input(),null,null),()->{}));assertEquals("SUCCEEDED",f.j.queryForObject("SELECT state FROM external_operation WHERE id=?",String.class,first.operationId()));assertEquals("FAILED",f.j.queryForObject("SELECT state FROM external_execution WHERE id=?",String.class,first.executionId()));assertEquals("SUCCEEDED",f.j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,retry.taskId()));assertEquals("FAILED",f.j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,lease.taskId()));}
}
